window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[111]={"id":"111","numero":111,"titre":"Dermatoses faciales","objectifs":[{"id":"111-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’acné","contenu":"<p>L’<span class=\"kw-def\">acné</span> est une <strong>dermatose <span class=\"kw-etio\">inflammatoire</span> chronique du follicule pilo-sébacé</strong>. Maladie <span class=\"kw-clinique\">non infectieuse</span> mais <span class=\"kw-clinique\">inflammatoire</span>, elle touche préférentiellement l’<span class=\"kw-clinique\">adolescent</span> (puberté : <span class=\"kw-chiffre\">12 ans</span> chez la fille, <span class=\"kw-chiffre\">14 ans</span> chez le garçon) et peut se prolonger ou débuter à l’âge adulte (femme <span class=\"kw-chiffre\">> 25 ans</span>).</p>\n\n      <div class=\"callout callout-info\">\n        <strong>Triade physiopathologique.</strong> Trois mécanismes intriqués : <span class=\"kw-clinique\">séborrhée</span> (hyperandrogénie périphérique), <span class=\"kw-clinique\">kératinisation infundibulaire</span> (genèse du comédon) et <span class=\"kw-clinique\">inflammation à Cutibacterium acnes</span> (anciennement <em>Propionibacterium acnes</em>). C’est <strong>l’<span class=\"kw-ci\">hypersensibilité</span> des récepteurs androgéniques du sébocyte</strong>, et non un excès d’androgènes circulants, qui sous-tend la maladie.\n      </div>","frequence":0},{"id":"111-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes physiopathologiques de l’acné","contenu":"<p>L’acné repose sur 3 mécanismes physiopathologiques intriqués au sein du follicule pilo-sébacé.</p>\n\n      <table >\n        <thead>\n          <tr><th>Mécanisme</th><th>Description</th><th><span class=\"kw-clinique\">Lésion</span> élémentaire générée</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Séborrhée</strong></td>\n            <td>\n              <span class=\"kw-def\">Augmentation de la production de sébum</span> par la glande sébacée.<br>\n              <strong>Physiologie :</strong> testostérone libre → transformée par la <span class=\"kw-clinique\">5α-réductase de type 1</span> en dihydrotestostérone → fixation sur les récepteurs androgéniques du sébocyte → sécrétion de sébum.<br>\n              <strong>Spécificité acné :</strong> les <span class=\"kw-clinique\">androgènes circulants sont à des taux normaux</span> ; c’est l’<span class=\"kw-alerte\">hyperandrogénie périphérique</span> (sensibilité particulière des récepteurs des sébocytes et kératinocytes) qui est responsable.\n            </td>\n            <td>Peau grasse et luisante</td>\n          </tr>\n          <tr>\n            <td><strong>Kératinisation infundibulaire</strong></td>\n            <td>\n              Formation du <span class=\"kw-def\">comédon</span> (accumulation de sébum, kératinocytes et mélanine remplissant le pore) par :<br>\n              <span class=\"kw-clinique\">Hyperprolifération</span> des kératinocytes du follicule pilo-sébacé ;<br>\n              <span class=\"kw-clinique\">Anomalies de différenciation</span> empêchant leur élimination normale.\n            </td>\n            <td><strong>Lésions rétentionnelles</strong> (comédons fermés et ouverts)</td>\n          </tr>\n          <tr>\n            <td><strong>Microbes &amp; inflammation</strong></td>\n            <td>\n              Flore anaérobie folliculaire dominée par <span class=\"kw-clinique\">Cutibacterium acnes</span> (Gram +, ex-<em>Propionibacterium acnes</em>).<br>\n              <em>C. acnes</em> sécrète de nombreux <span class=\"kw-clinique\">facteurs pro-inflammatoires</span>.<br>\n              Différentes <strong>souches</strong> à pouvoir <span class=\"kw-etio\">inflammatoire</span> variable : la flore du sujet acnéique diffère de celle du sujet sain.<br>\n              ⚠️ Acné = maladie inflammatoire, <strong>pas une maladie infectieuse</strong>.\n            </td>\n            <td><strong>Lésions inflammatoires</strong> (papules, pustules, nodules)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Atteinte cutanée / germe à connaître (item 111).</strong> Pour chaque dermatose faciale, un germe ou un acarien distinct est suspecté — ne pas confondre.\n      </div>\n\n      <table >\n        <thead>\n          <tr><th>Dermatose faciale</th><th>Germe / agent suspecté</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Acné</strong></td><td><em>Cutibacterium acnes</em> (anciennement <em>Propionibacterium acnes</em>)</td></tr>\n          <tr><td><strong>Rosacée</strong></td><td><em>Demodex folliculorum</em> (acarien)</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Dermatite</span> <span class=\"kw-clinique\">séborrhéique</span></strong></td><td><em><span class=\"kw-etio\">Malassezia</span> furfur</em> (levure)</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"111-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments cliniques permettant de diagnostiquer une acné","contenu":"<p>Diagnostic <span class=\"kw-clinique\">clinique</span>, reposant sur l’association de <strong>séborrhée + lésions rétentionnelles + lésions inflammatoires</strong> sur les zones séborrhéiques (visage central, dos, face antérieure du thorax).</p>\n\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-clinique\">Lésion</span></th><th>Description</th><th>Topographie / <span class=\"kw-clinique\">évolution</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Séborrhée</strong> <em>(constante)</em></td>\n            <td>Peau grasse et luisante</td>\n            <td>Partie centrale du visage (nez, front, menton, joues) ; cou ; dos ; face antérieure du thorax</td>\n          </tr>\n          <tr>\n            <td><strong>Comédons fermés</strong> (microkystes)</td>\n            <td><span class=\"kw-def\">Accumulation de sébum + kératine</span> dans le canal folliculaire dilaté par <span class=\"kw-clinique\">obstruction de son orifice</span><br>\n              → Petites papules de <span class=\"kw-chiffre\">2–3 mm</span>, couleur peau normale, parfois plus palpables que visibles</td>\n            <td>Peuvent <span class=\"kw-alerte\">s’enflammer</span> ⚠️</td>\n          </tr>\n          <tr>\n            <td><strong>Comédons ouverts</strong> (points noirs)</td>\n            <td>Accumulation de kératinocytes <span class=\"kw-clinique\">oxydés</span> au sein de l’orifice dilaté du canal infundibulaire<br>\n              → Lésions de <span class=\"kw-chiffre\">1–3 mm</span>, classiques « points noirs »</td>\n            <td>Peuvent s’<span class=\"kw-clinique\">expulser spontanément</span> ou s’enflammer</td>\n          </tr>\n          <tr>\n            <td><strong>Lésions inflammatoires superficielles</strong></td>\n            <td><strong>Papules</strong> (issues d’une <span class=\"kw-clinique\">lésion</span> rétentionnelle) : <span class=\"kw-chiffre\">&lt; 1 cm</span>, rouges, fermes, parfois douloureuses<br>\n              <strong>Pustules</strong> (issues de papules) : papules au sommet desquelles apparaît un <span class=\"kw-clinique\">contenu purulent jaune</span> (accumulation de <span class=\"kw-bio\">polynucléaires</span>)</td>\n            <td>Résorption ou <span class=\"kw-clinique\">évolution</span> vers la <span class=\"kw-clinique\">pustule</span></td>\n          </tr>\n          <tr>\n            <td><strong>Lésions inflammatoires profondes</strong></td>\n            <td><strong>Nodules</strong>&nbsp;: lésions de <span class=\"kw-chiffre\">&gt; 1 cm</span> atteignant le derme</td>\n            <td><span class=\"kw-clinique\">Évolution</span> possible vers <span class=\"kw-alerte\">abcès</span>, formation de <span class=\"kw-alerte\">cicatrices</span> ⚠️ ; si <span class=\"kw-alerte\">rupture</span> profonde : <span class=\"kw-clinique\">sinus</span> (nodules allongés très douloureux)</td>\n          </tr>\n          <tr>\n            <td><strong>Cicatrices</strong></td>\n            <td>Fréquentes, <span class=\"kw-clinique\">secondaires aux lésions inflammatoires</span> surtout prolongées</td>\n            <td>Peuvent être <strong>déprimées</strong> et <span class=\"kw-alerte\">hyperpigmentées</span> sur peau foncée</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Clé diagnostique.</strong> La <span class=\"kw-clinique\">présence de lésions rétentionnelles</span> (comédons fermés ou ouverts) est nécessaire au diagnostic — leur <span class=\"kw-alerte\">absence élimine le diagnostic d’acné</span> ⭐ (cf. obj-6 diagnostics différentiels).\n      </div>","frequence":1},{"id":"111-4","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir classer cliniquement une acné","contenu":"<p>La gradation clinique de l’acné se fait via l’échelle <span class=\"kw-def\">GEA</span> (<em>Global Evaluation Acne</em>) qui combine :</p>\n      <ul>\n        <li>l’<strong>extension</strong> des lésions sur le visage (<span class=\"kw-chiffre\">&lt; 50 %</span> · <span class=\"kw-chiffre\">&gt; 50 %</span> · tout le visage) ;</li>\n        <li>le <strong>nombre de lésions inflammatoires profondes</strong> (nodules).</li>\n      </ul>\n\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Grade</span> GEA</th><th>Tableau clinique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> 1 — très légère</strong></td>\n            <td>Pratiquement pas de lésions, <span class=\"kw-clinique\">rares comédons</span>, <span class=\"kw-clinique\">rares papules</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> 2 — légère</strong></td>\n            <td><span class=\"kw-clinique\">Comédons</span> + quelques <span class=\"kw-clinique\">papulo-pustules</span> sur <span class=\"kw-chiffre\">&lt; 50 %</span> du visage</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> 3 — moyenne</strong></td>\n            <td>Nombreux comédons et papulo-pustules sur <span class=\"kw-chiffre\">&gt; 50 %</span> du visage ; <span class=\"kw-clinique\">1 nodule</span> peut être présent</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> 4 — sévère</strong></td>\n            <td>Nombreux comédons et papulo-pustules sur <strong>tout le visage</strong>, <span class=\"kw-clinique\">rares nodules</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> 5 — très sévère</strong></td>\n            <td>Acné <span class=\"kw-alerte\">très inflammatoire</span> recouvrant le visage avec <span class=\"kw-alerte\">nodules</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Utilité clinique.</strong> Le <span class=\"kw-def\">grade</span> GEA conditionne directement la stratégie thérapeutique — topique seul (<span class=\"kw-chiffre\">grade 1</span>–2), topique + cyclines per os (grade 3–4), <span class=\"kw-ttt\">isotrétinoïne</span> per os d’emblée (grade 5). Cf. obj-7 pour le détail des indications.\n      </div>","frequence":0},{"id":"111-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître deux formes cliniques d’acné","contenu":"<p>Au-delà du tableau standard, plusieurs formes cliniques sont à identifier — communes, graves, ou particulières par leur <span class=\"kw-def\">terrain</span>.</p>\n\n      <h4 style=\"margin: 14px 0 6px 0;\">Formes communes</h4>\n      <table >\n        <thead>\n          <tr><th>Forme</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Acné mixte juvénile</strong></td>\n            <td>Forme la <strong>plus commune</strong>. Puberté : <span class=\"kw-chiffre\">12 ans</span> fille, <span class=\"kw-chiffre\">14 ans</span> garçon. Sévérité variable :<br>\n              <strong>Minime/modérée :</strong> lésions rétentionnelles + inflammatoires superficielles ;<br>\n              <strong>Sévère :</strong> présence de <span class=\"kw-alerte\">nodules</span> ; peut s’étendre au tronc.</td>\n          </tr>\n          <tr>\n            <td><strong>Acné rétentionnelle</strong></td>\n            <td>Forme la plus fréquente de l’acné débutante → essentiellement <span class=\"kw-clinique\">microkystes</span> et <span class=\"kw-clinique\">comédons ouverts</span> sur le visage.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin: 14px 0 6px 0;\">Formes graves 🔥</h4>\n      <table >\n        <thead>\n          <tr><th>Forme</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Acné nodulaire (conglobata)</strong></td>\n            <td>\n              Nodules inflammatoires pouvant évoluer vers <span class=\"kw-alerte\">abcès</span> ou se fistuliser en profondeur (<span class=\"kw-alerte\">sinus</span>) ;<br>\n              Extension au tronc fréquente (surtout garçon) ;<br>\n              <span class=\"kw-clinique\">Évolution</span> <span class=\"kw-clinique\">chronique</span> avec formation de <strong>cicatrices</strong> souvent importantes.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Acné fulminante</strong></td>\n            <td>\n              « Acné nodulaire aiguë, fébrile et ulcéreuse », exceptionnelle, plutôt <strong>garçon</strong>.<br>\n              <strong>Début brutal :</strong> <span class=\"kw-clinique\">AEG</span> + <span class=\"kw-alerte\">hyperthermie 39–40 °C</span> + <span class=\"kw-clinique\">arthralgies</span> ;<br>\n              Nodules inflammatoires très nombreux pouvant se compliquer d’<span class=\"kw-alerte\">ulcérations nécrotiques et hémorragiques</span> ⚠️ ;<br>\n              <span class=\"kw-bio\">Hyperleucocytose</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin: 14px 0 6px 0;\">Formes particulières (<span class=\"kw-def\">terrain</span> ou étiologie)</h4>\n      <table >\n        <thead>\n          <tr><th>Forme</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Acné néonatale</strong></td>\n            <td>Androgènes maternels → visage dès les <span class=\"kw-chiffre\">1ʳᵉˢ semaines de vie</span> → régression spontanée en <span class=\"kw-chiffre\">quelques semaines</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Acné révélant une endocrinopathie</strong></td>\n            <td>À évoquer devant : acné <strong>féminine grave et résistante</strong> ; ou acné + signes d’<span class=\"kw-clinique\">hyperandrogénie</span> (hirsutisme, alopécie, troubles des règles).<br>\n              <strong>Bilan :</strong> <span class=\"kw-imagerie\">échographie abdomino-pelvienne</span> (SOPK) + <span class=\"kw-bio\">testostérone libre, 17OH-progestérone, sulfate de DHA, Δ4-androstènedione</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Acné prépubertaire</strong></td>\n            <td>Début précoce pré-pubertaire, essentiellement <span class=\"kw-clinique\">rétentionnelle</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Acnés exogènes</strong></td>\n            <td>Prédominance des lésions <strong>rétentionnelles</strong> :<br>\n              Acnés aux <span class=\"kw-clinique\">cosmétiques</span> (crèmes hydratantes avec huiles végétales, poudres pigmentaires) — visage ;<br>\n              Acnés aux <span class=\"kw-clinique\">huiles minérales</span> : « boutons d’huile » des cuisses/bras (garagistes, mécaniciens, fraiseurs).</td>\n          </tr>\n          <tr>\n            <td><strong>Acné de la femme adulte</strong></td>\n            <td>Acné juvénile prolongée, ou plus rarement débutant tardivement. Femme <span class=\"kw-chiffre\">&gt; 25 ans</span> :<br>\n              Lésions <strong>rétentionnelles</strong> sur la partie haute du visage ;<br>\n              Lésions <strong>inflammatoires</strong> (papules/nodules) sur la partie basse (mandibule).</td>\n          </tr>\n          <tr>\n            <td><strong>Acné excoriée (dermatillomanie)</strong></td>\n            <td>Forme presque exclusivement <strong>féminine</strong>. Lésions provoquées par <span class=\"kw-clinique\">manipulations excessives</span> de la peau du visage → érosions.<br>\n              Témoigne parfois de difficultés psychologiques : trouble anxieux du spectre <span class=\"kw-clinique\">CRCC</span> (Comportements Répétitifs Centrés sur le Corps).</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"111-6","rang":"B","rubrique":"Contenu multimédia","titre":"Savoir reconnaître les différentes formes cliniques d’acné","contenu":"<p>Reconnaissance visuelle attendue — le diagnostic d’acné étant <span class=\"kw-clinique\">purement clinique</span>, savoir <strong>nommer la forme</strong> sur une photo conditionne le <span class=\"kw-def\">grade</span> GEA et la PEC.</p>\n\n      <table >\n        <thead>\n          <tr><th>Forme à reconnaître</th><th>Sémiologie visuelle clé</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Acné rétentionnelle</strong></td>\n            <td>Visage couvert de <span class=\"kw-clinique\">microkystes</span> (papules couleur peau,<span class=\"kw-chiffre\"> 2–3 mm</span>) et de <span class=\"kw-clinique\">comédons ouverts</span> (points noirs,<span class=\"kw-chiffre\"> 1–3 mm</span>), <strong>sans</strong> ou avec peu de lésions inflammatoires.</td>\n          </tr>\n          <tr>\n            <td><strong>Acné mixte juvénile</strong></td>\n            <td>Coexistence sur le visage de <span class=\"kw-clinique\">comédons</span> + <span class=\"kw-clinique\">papules</span> + <span class=\"kw-clinique\">pustules</span> sur fond <span class=\"kw-clinique\">séborrhéique</span>. Atteinte du dos/torse possible.</td>\n          </tr>\n          <tr>\n            <td><strong>Acné nodulaire (conglobata)</strong></td>\n            <td><span class=\"kw-alerte\">Nodules inflammatoires</span> &gt;<span class=\"kw-chiffre\"> 1 cm</span>, <span class=\"kw-clinique\">abcès</span>, sinus fistulisés, <strong>cicatrices déprimées</strong> et hyperpigmentées (visage, dos, tronc).</td>\n          </tr>\n          <tr>\n            <td><strong>Acné fulminante</strong></td>\n            <td>Nodules inflammatoires nombreux + <span class=\"kw-alerte\">ulcérations nécrotiques et hémorragiques</span> + contexte fébrile (<span class=\"kw-chiffre\">≥ 39 °C</span>) + <span class=\"kw-clinique\">AEG</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Acné excoriée</strong></td>\n            <td>Femme jeune, <span class=\"kw-clinique\">érosions</span> linéaires et croûteuses sur les pommettes et le menton, à la place attendue de papules/pustules — lésions « grattées ».</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>À compléter (images).</strong> Les fiches sources du dossier <code>111/Dermatoses faciales (111)/Acné/</code> renvoient à des images (rétentionnelles, papules/pustules, nodulaire, cicatrices) mais aucun fichier exploitable n’est joint au build initial. Kevin déposera des photos cliniques de référence dans <code>assets/images/111/</code> (forme rétentionnelle, mixte juvénile, nodulaire/conglobata, fulminante, excoriée) — chaque image sera ensuite intégrée via <code>&lt;figure class=\"obj-figure\"&gt;</code>.\n      </div>\n      <!-- TODO Kevin : déposer photos cliniques acné dans assets/images/111/ -->","frequence":1},{"id":"111-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître deux diagnostics différentiels d’acné","contenu":"<div class=\"callout callout-info\">\n        <strong>Règle 0.</strong> L’<span class=\"kw-alerte\">absence de lésions rétentionnelles (comédons)</span> sur le visage d’un patient présentant des papulo-pustules <strong>élimine le diagnostic d’acné</strong> ⭐. Il faut alors rechercher une autre cause de <span class=\"kw-clinique\">folliculite</span>.\n      </div>\n\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Diagnostic différentiel</span></th><th>Caractéristiques discriminantes</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Folliculite</span> médicamenteuse</strong></td>\n            <td>\n              <strong>Début brutal</strong> + régression à l’arrêt du médicament ;<br>\n              Lésions <span class=\"kw-clinique\">monomorphes</span>, papulo-pustules <span class=\"kw-alerte\">sans comédons</span> ❌ ;<br>\n              <strong>Médicaments classiques :</strong> androgènes (sportifs/culturistes), progestatifs de synthèse et COP, <span class=\"kw-ttt\">corticostéroïdes</span>, antiépileptiques, antituberculeux, vitamine B12, halogènes, sels de <span class=\"kw-ttt\">lithium</span>, <span class=\"kw-ttt\">immunosuppresseurs</span> (<span class=\"kw-ttt\">azathioprine</span>, <span class=\"kw-ttt\">ciclosporine</span>), thérapies ciblées (anti-EGF, AC monoclonaux, anti-kinases).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Folliculites infectieuses</strong></td>\n            <td>Folliculites <span class=\"kw-clinique\">bactériennes</span>, à <span class=\"kw-clinique\">Demodex</span> (acarien), à <span class=\"kw-clinique\">Candida</span> ;<br>\n              Pas de comédons ; contexte (immunodépression, macération).</td>\n          </tr>\n          <tr>\n            <td><strong>Rosacée</strong></td>\n            <td>Papulo-pustuleuse ou granulomateuse ;<br>\n              <span class=\"kw-def\">Terrain</span> différent (adulte &gt;<span class=\"kw-chiffre\"> 20 ans</span>, <span class=\"kw-clinique\">phototype</span> clair, F &gt; H) ; <span class=\"kw-alerte\">pas de comédons</span> ❌ ; bouffées vasomotrices ; télangiectasies. Cf. obj-10.</td>\n          </tr>\n          <tr>\n            <td><strong>Syphilides acnéiformes</strong></td>\n            <td>IST à <em>Treponema pallidum</em> au <span class=\"kw-def\">stade</span> secondaire — papulo-pustules « acnéiformes » avec atteinte palmo-plantaire associée, polyADP, contexte épidémiologique. <span class=\"kw-bio\">Sérologie syphilitique</span> au moindre doute.</td>\n          </tr>\n          <tr>\n            <td><strong>Sarcoïdose cutanée</strong></td>\n            <td>Forme papulo-nodulaire faciale, parfois acnéiforme ; pas de comédons ; <span class=\"kw-bio\">infiltrats granulomateux</span> à la <span class=\"kw-bio\">biopsie</span> ; bilan systémique.</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"111-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les traitements systémiques et topiques de l’acné","contenu":"<p>L’arsenal thérapeutique de l’acné se répartit entre <span class=\"kw-clinique\">traitements locaux</span> (<span class=\"kw-ttt\">rétinoïdes</span>, peroxyde de benzoyle, ATB topiques) et <span class=\"kw-clinique\">traitements généraux</span> (cyclines, gluconate de zinc, <span class=\"kw-ttt\">isotrétinoïne</span>, hormonothérapie). Les traitements généraux sont <strong>toujours associés</strong> à un traitement local, <strong>sauf isotrétinoïne</strong>.</p>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-ci\">Contre-indication</span> absolue.</strong> Les <span class=\"kw-alerte\">dermocorticoïdes</span> sont <strong><span class=\"kw-ci\">contre-indiqués</span></strong> dans l’acné ❌.\n      </div>\n\n      <h4 style=\"margin: 14px 0 6px 0;\">Traitements locaux</h4>\n      <table >\n        <thead>\n          <tr><th></th><th><span class=\"kw-ttt\">Rétinoïdes</span> topiques</th><th>Peroxyde de benzoyle</th><th>Antibiotiques locaux</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Action</strong></td>\n            <td><span class=\"kw-clinique\">Kératolytique (comédolytique)</span> sur comédons et microkystes</td>\n            <td>Légèrement comédolytique + puissant <span class=\"kw-clinique\">anti-bactérien</span> (lésions inflammatoires superficielles) → <strong>pas de résistance</strong> connue ✅</td>\n            <td>Anti-<span class=\"kw-etio\">bactérien</span> + anti-<span class=\"kw-etio\">inflammatoire</span> non spécifique (action modeste)</td>\n          </tr>\n          <tr>\n            <td><strong>Molécules</strong></td>\n            <td>1ʳᵉ génération : <strong>Trétinoïne</strong> (acide rétinoïque tout-trans).<br>\n              2ⁿᵈ génération : <strong><span class=\"kw-ttt\">Isotrétinoïne</span> topique</strong> (acide 13-cis-rétinoïque), <strong>Adapalène</strong>.</td>\n            <td>Concentration <strong><span class=\"kw-chiffre\">2,5 %</span> ou <span class=\"kw-chiffre\">5 %</span></strong> sur le visage, <strong><span class=\"kw-chiffre\">10 %</span></strong> possible sur le dos.<br>\n              ⇒ Peut être utilisé chez la <span class=\"kw-clinique\">femme enceinte</span>.</td>\n            <td><strong>Érythromycine <span class=\"kw-chiffre\">4 %</span></strong> ⇒ utilisable chez la femme enceinte.<br>\n              <strong>Clindamycine</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Application</strong></td>\n            <td>Le <strong>soir</strong> (détruits par <span class=\"kw-etio\">UV</span>, photosensibilisants), sur <strong>tout le visage</strong>, pas seulement sur les lésions.</td>\n            <td>Le soir, tout le visage.</td>\n            <td>Le soir.</td>\n          </tr>\n          <tr>\n            <td><strong>EI / limites</strong></td>\n            <td><span class=\"kw-alerte\">Irritation</span> dose-dépendante (adapter la posologie)</td>\n            <td>Irritation ; <span class=\"kw-clinique\">photo-toxicité</span> ; <span class=\"kw-clinique\">décoloration des vêtements</span></td>\n            <td><span class=\"kw-alerte\">Résistances bactériennes</span> en augmentation (notamment macrolides) → <strong>jamais en monothérapie</strong> ⚠️ ; durée <strong><span class=\"kw-chiffre\">≤ 4 semaines</span></strong>. Toujours associé à péroxyde de benzoyle ou <span class=\"kw-ttt\">rétinoïde</span> topique.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin: 14px 0 6px 0;\">Cyclines per os (ATB systémique de 1ᵉʳ choix)</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Mécanisme</strong></td>\n            <td>Inhibition de la synthèse protéique par liaison à la sous-unité <span class=\"kw-chiffre\">30S</span> du ribosome.</td>\n          </tr>\n          <tr>\n            <td><strong>Pharmacocinétique</strong></td>\n            <td>Très bonne biodisponibilité orale, <strong>excellente <span class=\"kw-imagerie\">diffusion</span> osseuse</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Pharmacodynamie</strong></td>\n            <td><em>Bactériostatique</em>.</td>\n          </tr>\n          <tr>\n            <td><strong>Molécules utilisées</strong></td>\n            <td><strong>Doxycycline</strong>, <strong>lymécycline</strong>. Durée moyenne : <span class=\"kw-chiffre\">3 mois</span> (résistance au-delà). Activité anti-<span class=\"kw-clinique\">séborrhéique</span> et anti-<span class=\"kw-etio\">inflammatoire</span> à des doses inférieures aux doses anti-bactériennes.</td>\n          </tr>\n          <tr>\n            <td><strong>Effets secondaires</strong></td>\n            <td><span class=\"kw-clinique\">Phototoxicité</span> (<span class=\"kw-ttt\">doxycycline</span> +++) → éviction solaire ;<br>\n              Troubles digestifs avec <span class=\"kw-alerte\">ulcération œsophagienne</span> → prise PO au cours d’un repas, grand verre d’eau, position assise/debout, pas s’allonger <span class=\"kw-chiffre\">30 min</span> après ;<br>\n              <span class=\"kw-clinique\">Dyschromie dentaire</span> (brunâtre/jaunâtre) + hypoplasie de l’émail si prescription avant <span class=\"kw-chiffre\">8 ans</span> ;<br>\n              <span class=\"kw-alerte\">DRESS</span> (notamment minocycline → réservée à l’absence d’alternative).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ci\">Contre-indications</span></strong></td>\n            <td>Enfant &lt;<span class=\"kw-chiffre\"> 8 ans</span>, <span class=\"kw-alerte\">femme enceinte</span> ;<br>\n              <strong>Ne jamais associer</strong> aux <span class=\"kw-alerte\">rétinoïdes systémiques</span> (risque d’<span class=\"kw-alerte\">HTIC</span>) ni à un <span class=\"kw-alerte\">ATB topique</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Précautions</strong></td>\n            <td>Pas de prise concomitante de calcium (laitages, sels de calcium) ou anti-acides → diminue l’absorption.</td>\n          </tr>\n          <tr>\n            <td><strong>Alternatives</strong></td>\n            <td><strong>Macrolides</strong> (<span class=\"kw-ttt\">érythromycine</span>, roxithromycine, josamycine) : courte période, en cas de CI aux cyclines (femme enceinte, jeune enfant).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin: 14px 0 6px 0;\"><span class=\"kw-ttt\">Isotrétinoïne</span> per os (le plus puissant — sébostatique)</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Action</strong></td>\n            <td>Inhibiteur non hormonal de la sécrétion sébacée induisant l’<span class=\"kw-clinique\">apoptose des sébocytes</span>. <strong>Médicament le plus puissant</strong> et <strong>seul traitement curatif</strong> de l’acné (les autres traitements généraux sont suspensifs).</td>\n          </tr>\n          <tr>\n            <td><strong>Indications</strong></td>\n            <td><strong>1ʳᵉ intention</strong> dans les acnés très sévères (GEA 5) ;<br>\n              En cas d’échec du traitement de 1ʳᵉ intention dans les acnés moyennes (GEA 3) ou sévères (GEA 4).</td>\n          </tr>\n          <tr>\n            <td><strong>Durée</strong></td>\n            <td>Jusqu’à atteinte d’une dose cumulée de <span class=\"kw-chiffre\">120–150 mg/kg</span> (<span class=\"kw-chiffre\">9 à 12 mois</span> en moyenne).</td>\n          </tr>\n          <tr>\n            <td><strong>Effets secondaires</strong></td>\n            <td>\n              <span class=\"kw-bio\">Élévation des transaminases</span> + hyperlipidémie ;<br>\n              <span class=\"kw-clinique\">Exacerbation de l’acné</span> (poussée <span class=\"kw-etio\">inflammatoire</span>) pendant les <span class=\"kw-chiffre\">4 premières semaines</span> ;<br>\n              <span class=\"kw-clinique\">Sécheresse cutanéo-muqueuse</span> dose-dépendante : <strong>chéilite</strong>, <strong><span class=\"kw-clinique\">xérose</span></strong> cutanée, <strong>conjonctivite</strong> (proscrire le port de lentilles), <strong>rhinite sèche</strong> (épistaxis possibles) ;<br>\n              <span class=\"kw-alerte\">Risque d’HTIC</span> si association aux <strong>cyclines</strong> ⛔ (CI) ;<br>\n              Douleurs ligamentaires ;<br>\n              Troubles de l’humeur — évaluer le risque de <span class=\"kw-clinique\">dépression</span> ;<br>\n              <span class=\"kw-alerte\">Tératogénicité majeure</span> ⚠️.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Précautions</strong></td>\n            <td>\n              Réglementation spéciale de prescription/délivrance avec carnet ;<br>\n              <span class=\"kw-clinique\">Évacuer les lésions rétentionnelles avant</span> l’instauration (diminue le risque de poussée) ;<br>\n              <span class=\"kw-bio\">Surveillance transaminases (ASAT/ALAT) + bilan lipidique</span> tous les <span class=\"kw-chiffre\">3 mois</span> ;<br>\n              Femme en âge de procréer : <span class=\"kw-ci\">contraception efficace</span> (cf. obj-8).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège pharmaco — ne pas confondre acitrétine et <span class=\"kw-ttt\">isotrétinoïne</span>.</strong>\n      </div>\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>Acitrétine</th><th>Isotrétinoïne</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Indication</strong></td><td><span class=\"kw-clinique\">Psoriasis</span></td><td>Acné</td></tr>\n          <tr><td><strong>Contraception après arrêt</strong></td><td><span class=\"kw-chiffre\">2 ans</span></td><td><span class=\"kw-chiffre\">1 mois</span></td></tr>\n          <tr><td><strong>β-hCG après arrêt</strong></td><td>Pendant <span class=\"kw-chiffre\">2 ans</span></td><td>Mensuels puis à <span class=\"kw-chiffre\">5 semaines</span> de la fin</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Suivi</span> <span class=\"kw-ttt\">biologique</span></strong></td><td>Bilan trimestriel lipidique + hépatique</td><td>Bilan trimestriel lipidique + hépatique</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin: 14px 0 6px 0;\">Autres traitements généraux</h4>\n      <table >\n        <thead>\n          <tr><th>Classe</th><th>Indication / précautions</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Gluconate de zinc</strong></td>\n            <td>Action anti-<span class=\"kw-etio\">inflammatoire</span> (inférieure aux cyclines). Utile en cas de CI aux cyclines : acné <strong>prépubertaire</strong>, été (pas de photosensibilisation), <strong><span class=\"kw-ci\">grossesse</span></strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Hormonothérapie œstroprogestative</strong></td>\n            <td>Indiquée chez la <strong>femme avec besoin contraceptif</strong> (jamais en l’absence de besoin contraceptif).<br>\n              <strong>1ʳᵉ intention :</strong> progestatif à faible activité androgénique = <span class=\"kw-ttt\">lévonorgestrel</span>.<br>\n              <strong>2ⁿᵈ intention :</strong> <span class=\"kw-ttt\">norgestimate</span>.<br>\n              Si échec : autres options en concertation avec un gynécologue.<br>\n              <strong>Acétate de cyprotérone + éthinylestradiol :</strong> possible en tenant compte des recommandations de l’ANSM (risque thromboembolique).<br>\n              ⚠️ <span class=\"kw-alerte\">À ne pas prescrire pendant un traitement par isotrétinoïne</span> (efficacité contraceptive insuffisante).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin: 14px 0 6px 0;\">Indications selon le <span class=\"kw-def\">grade</span> GEA (traitement d’attaque ≈<span class=\"kw-chiffre\"> 3 mois</span>)</h4>\n      <table >\n        <thead>\n          <tr><th>Grade</th><th>1ʳᵉ intention</th><th>Si échec à<span class=\"kw-chiffre\"> 3 mois</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1 — très légère</strong></td>\n            <td>Traitement local selon les lésions :<br>\n              Rétentionnelles → <strong><span class=\"kw-ttt\">rétinoïdes</span></strong> ;<br>\n              Papules/pustules → <strong>peroxyde de benzoyle</strong>.</td>\n            <td>Peroxyde de benzoyle + <span class=\"kw-ttt\">rétinoïdes</span></td>\n          </tr>\n          <tr>\n            <td><strong>2 — légère</strong></td>\n            <td><strong>Peroxyde de benzoyle + <span class=\"kw-ttt\">rétinoïde</span> topique</strong></td>\n            <td>Intensification du traitement de 1ʳᵉ intention : ATB topique + <span class=\"kw-ttt\">rétinoïde</span> ; ou ATB topique + acide azélaïque ; ou cyclines + rétinoïdes + peroxyde de benzoyle.</td>\n          </tr>\n          <tr>\n            <td><strong>3 — moyenne</strong></td>\n            <td>Traitement <strong>topique combiné</strong> ± cyclines</td>\n            <td><span class=\"kw-ttt\">Isotrétinoïne</span> per os</td>\n          </tr>\n          <tr>\n            <td><strong>4 — sévère</strong></td>\n            <td>Cyclines + traitement topique combiné</td>\n            <td><span class=\"kw-ttt\">Isotrétinoïne</span> per os (peut être débutée avant <span class=\"kw-chiffre\">3 mois</span> si récidive rapide ou risque cicatriciel)</td>\n          </tr>\n          <tr>\n            <td><strong>5 — très sévère</strong></td>\n            <td><span class=\"kw-ttt\">Isotrétinoïne per os d’emblée</span></td>\n            <td>—</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Traitement d’entretien.</strong> Une fois la rémission obtenue (GEA 0), maintenir le traitement d’entretien <strong>aussi longtemps que nécessaire</strong> même en cas de disparition totale : <span class=\"kw-ttt\">adapalène</span> ± <span class=\"kw-ttt\">peroxyde de benzoyle</span>.\n      </div>","frequence":2},{"id":"111-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les recommandations en termes de contraception dans l’acné","contenu":"<p>La contraception intervient à <strong>deux titres</strong> dans la PEC de l’acné : comme <span class=\"kw-clinique\">protection obligatoire</span> chez toute femme en âge de procréer recevant de l’<span class=\"kw-ttt\">isotrétinoïne</span> (<span class=\"kw-alerte\">tératogénicité majeure</span>) ; et comme <span class=\"kw-clinique\">option thérapeutique</span> chez la femme avec besoin contraceptif via l’hormonothérapie œstroprogestative.</p>\n\n      <h4 style=\"margin: 14px 0 6px 0;\">1. Contraception sous <span class=\"kw-ttt\">isotrétinoïne</span></h4>\n      <table >\n        <thead>\n          <tr><th>Modalité</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Démarrage</strong></td>\n            <td><span class=\"kw-ci\">Contraception efficace</span> débutée <span class=\"kw-chiffre\">1 mois avant</span> le début du traitement.</td>\n          </tr>\n          <tr>\n            <td><strong>Maintien</strong></td>\n            <td>Poursuivie pendant <strong>toute la durée</strong> du traitement.</td>\n          </tr>\n          <tr>\n            <td><strong>Arrêt</strong></td>\n            <td>Poursuivie <span class=\"kw-chiffre\">1 mois après</span> l’arrêt de l’<span class=\"kw-ttt\">isotrétinoïne</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>β-hCG plasmatiques</strong></td>\n            <td>Contrôles <strong>mensuels</strong> pendant le traitement, et un dernier dosage <span class=\"kw-chiffre\">5 semaines après</span> l’arrêt.</td>\n          </tr>\n          <tr>\n            <td><strong>Consentement</strong></td>\n            <td>Signé par la patiente (ou par le représentant légal si mineure).</td>\n          </tr>\n          <tr>\n            <td><strong>Carnet</strong></td>\n            <td>Carnet de prescription/délivrance obligatoire.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique — acétate de cyprotérone + éthinylestradiol</strong> ne doit <span class=\"kw-alerte\">pas être prescrit pendant un traitement par isotrétinoïne</span> (<em>efficacité contraceptive insuffisante</em> dans ce contexte).\n      </div>\n\n      <h4 style=\"margin: 14px 0 6px 0;\">2. Hormonothérapie œstroprogestative à visée acnéique + contraceptive</h4>\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Molécule / précaution</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Indication</strong></td>\n            <td>Femme acnéique <strong>ayant un besoin contraceptif</strong>. En l’absence de besoin contraceptif, <strong>ne pas prescrire</strong> un œstroprogestatif uniquement pour l’acné ❌.</td>\n          </tr>\n          <tr>\n            <td><strong>1ʳᵉ intention</strong></td>\n            <td>Progestatif à <span class=\"kw-clinique\">faible activité androgénique</span> : <span class=\"kw-ttt\">lévonorgestrel</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>2ⁿᵈ intention</strong></td>\n            <td><span class=\"kw-ttt\">Norgestimate</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Si échec</strong></td>\n            <td>Autres options contraceptives en concertation avec la patiente et un gynécologue.</td>\n          </tr>\n          <tr>\n            <td><strong>Acétate de cyprotérone + éthinylestradiol</strong></td>\n            <td>Possible en tenant compte des recommandations <span class=\"kw-clinique\">ANSM</span> (<span class=\"kw-alerte\">risque thromboembolique</span>).<br>\n              <strong>CI</strong> : traitement concomitant par <span class=\"kw-ttt\">isotrétinoïne</span> (cf. ci-dessus).</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"111-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les conseils hygiéno-diététiques à prodiguer à un patient acnéique","contenu":"<p>Les conseils hygiéno-diététiques font partie intégrante de la PEC — l’<strong>observance</strong> reste le facteur limitant le plus fréquent, en particulier chez l’adolescent.</p>\n\n      <table >\n        <thead>\n          <tr><th>Thème</th><th>Conseil</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Délai d’efficacité</strong></td>\n            <td>Les effets du traitement ne sont <span class=\"kw-alerte\">jamais rapides</span> ⚠️ : il faut <span class=\"kw-chiffre\">2 à 3 mois</span> en moyenne pour un résultat appréciable → <strong>prévenir le patient</strong> (explique souvent l’observance médiocre chez les adolescents).</td>\n          </tr>\n          <tr>\n            <td><strong>Soins quotidiens</strong></td>\n            <td>\n              <strong>Ne pas presser les comédons</strong> ❌ ;<br>\n              Traitement local appliqué le <strong>soir</strong>, sur <strong>tout le visage</strong>, <strong>pas uniquement sur les lésions</strong> ;<br>\n              Crème <span class=\"kw-clinique\">hydratante</span> le <strong>matin</strong> pour protéger la barrière cutanée de l’irritation induite par les topiques ;<br>\n              « Nettoyages de la peau » = simple complément éventuel, jamais central ;<br>\n              Soins d’hygiène <span class=\"kw-clinique\">indispensables mais guidés</span>, idem pour la cosmétologie ;<br>\n              <strong>Inutile voire préjudiciable</strong> : antiseptique sur les lésions ❌ ; toilette « énergique » ❌.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Soleil</strong></td>\n            <td>Réduit transitoirement le caractère <span class=\"kw-etio\">inflammatoire</span> des lésions, <strong>mais</strong> facilite la <span class=\"kw-clinique\">comédogenèse</span> en épaississant la peau :<br>\n              → <span class=\"kw-alerte\">amélioration estivale typiquement suivie d’une poussée d’acné en automne</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Alimentation</strong></td>\n            <td><strong>Pas de régime alimentaire à suivre</strong> ❌ — aucune éviction n’est recommandée.</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"111-11","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer une rosacée","contenu":"<p>La <span class=\"kw-def\">rosacée</span> est une maladie faciale fréquente longtemps confondue avec l’acné (le terme « acné-rosacée » doit être <strong>abandonné</strong>). Diagnostic <span class=\"kw-clinique\">clinique</span> : <span class=\"kw-def\">terrain</span> + sémiologie évocatrice + <strong>absence de lésions rétentionnelles</strong>.</p>\n\n      <h4 style=\"margin: 14px 0 6px 0;\"><span class=\"kw-def\">Terrain</span> et facteurs</h4>\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Phototype</span></strong></td><td>Sujets à peau claire, yeux clairs, cheveux clairs</td></tr>\n          <tr><td><strong>Sex-ratio</strong></td><td>Prédominance <strong>féminine</strong> (<span class=\"kw-chiffre\">2 F / 1 H</span>)</td></tr>\n          <tr><td><strong>Âge</strong></td><td>Adulte <span class=\"kw-chiffre\">&gt; 20 ans</span>, pic de fréquence à <span class=\"kw-chiffre\">40–50 ans</span></td></tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Physiopathologie</span></strong></td>\n            <td>Associe 2 éléments :<br>\n              <span class=\"kw-clinique\">Anomalies vasculaires</span> (bouffées vasomotrices, télangiectasies) ;<br>\n              <span class=\"kw-clinique\">Réponse immunitaire</span> entraînant l’inflammation.</td>\n          </tr>\n          <tr>\n            <td><strong>Facteurs déclenchants</strong></td>\n            <td>Climat continental (amplitudes thermiques été/hiver) ; travail à la chaleur ; <span class=\"kw-clinique\">exposition solaire</span> (déclenche la maladie + augmente signes fonctionnels et rougeur).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span></strong></td>\n            <td><span class=\"kw-clinique\">Chronique</span>, émaillée de poussées de papules et pustules sans facteur déclenchant particulier ;<br>\n              Phases inflammatoires régressent avec l’âge.</td>\n          </tr>\n          <tr>\n            <td><strong>Complications oculaires</strong></td>\n            <td>Fréquentes : <span class=\"kw-chiffre\">30–50 %</span> ont des signes subjectifs ⚠️ → sécheresse, <span class=\"kw-alerte\">conjonctivites</span>, <span class=\"kw-alerte\">blépharites</span>, voire <span class=\"kw-alerte\">kératites</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin: 14px 0 6px 0;\">3 formes cliniques successives (le passage n’est pas obligatoire ⭐)</h4>\n      <table >\n        <thead>\n          <tr><th>Forme</th><th>Sémiologie</th><th>Localisations</th><th>Facteurs déclenchants</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Vasculaire paroxystique</strong><br><em>(« flushes »)</em></td>\n            <td>Bouffées vasomotrices : poussées de rougeur paroxystique + sensation de chaleur. <span class=\"kw-alerte\">Pas de signes systémiques</span> ❌.</td>\n            <td>Visage et cou</td>\n            <td>\n              <span class=\"kw-clinique\">Changements de température</span> (peut induire une thermophobie) ;<br>\n              <span class=\"kw-clinique\">Boissons et aliments chauds</span> ;<br>\n              <span class=\"kw-clinique\">Alcool</span> ;<br>\n              <span class=\"kw-clinique\">Aliments épicés</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Vasculaire permanente</strong><br><em>(rosacée érythémato-télangiectasique)</em></td>\n            <td><span class=\"kw-clinique\">Érythème facial permanent</span> + <span class=\"kw-clinique\">télangiectasies</span> (couperose)</td>\n            <td>Joues, nez, menton, partie médiane du front</td>\n            <td>Peut s’associer aux bouffées vasomotrices</td>\n          </tr>\n          <tr>\n            <td><strong>Papulo-pustuleuse</strong><br><em>(forme la plus caractéristique)</em></td>\n            <td><span class=\"kw-clinique\">Papules inflammatoires</span> + <span class=\"kw-clinique\">pustules</span> sur fond d’<span class=\"kw-clinique\">érythème</span> permanent</td>\n            <td>Visage central</td>\n            <td>—</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin: 14px 0 6px 0;\">Forme hypertrophique : rhinophyma</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td>Touche principalement les <strong>hommes</strong> (<span class=\"kw-chiffre\">95 %</span>), souvent <span class=\"kw-chiffre\">&gt; 50 ans</span>.<br>\n              ⚠️ <span class=\"kw-alerte\">L’alcool n’est pas en cause</span> (idée reçue à ne pas évoquer).</td>\n          </tr>\n          <tr>\n            <td><strong>Manifestations</strong></td>\n            <td>Nez augmente de volume, diffusément rouge, orifices folliculaires dilatés ;<br>\n              <span class=\"kw-clinique\">Épaississement progressif</span> de la peau qui devient fibreuse → aspect classique de la « trogne ».</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span></strong></td>\n            <td>Une fois installé, ne régresse plus et n’est sensible à <strong>aucun traitement médical</strong> ❌.</td>\n          </tr>\n          <tr>\n            <td><strong>Traitement</strong></td>\n            <td><span class=\"kw-ttt\">Réduction</span> <strong>chirurgicale</strong> ou par <span class=\"kw-ttt\">laser CO2</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin: 14px 0 6px 0;\">Diagnostics différentiels</h4>\n      <table >\n        <thead>\n          <tr><th>Pathologie</th><th>Caractéristiques discriminantes</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Acné</strong></td>\n            <td><span class=\"kw-def\">Terrain</span> différent (adolescent) ; <span class=\"kw-clinique\">signes rétentionnels</span> (comédons, microkystes) ; séborrhée ; pas de bouffées vasomotrices.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Dermatite</span> <span class=\"kw-clinique\">séborrhéique</span></strong></td>\n            <td>Fond érythémateux + <span class=\"kw-clinique\">squames grasses</span> ;<br>\n              Localisations différentes : ailes du nez, sillons naso-labiaux, sourcils, glabelle, lisière antérieure du cuir chevelu ;<br>\n              ⚠️ Association rosacée + DS possible chez un même individu → « dermatose mixte du visage ».</td>\n          </tr>\n          <tr>\n            <td><strong>Rosacée stéroïdienne</strong></td>\n            <td><span class=\"kw-alerte\">Toujours rechercher</span> une application de <span class=\"kw-ttt\">corticoïdes</span> locaux devant une rosacée de sémiologie inhabituelle ⚠️ :<br>\n              Induite par <span class=\"kw-ttt\">corticothérapie locale forte et prolongée sur le visage</span> ;<br>\n              <span class=\"kw-clinique\">Dépendance majeure aux corticoïdes</span> ;<br>\n              <span class=\"kw-clinique\">Érythème</span> desquamatif rouge sombre/violacé + multiples télangiectasies ;<br>\n              Localisations : zones <strong>péri-buccale</strong> et/ou <strong>péri-oculaire</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Lupus</span> érythémateux</strong></td>\n            <td>Souvent évoqué dans les phases précoces, mais :<br>\n              Pas de bouffées vasomotrices, pas de pustules ❌ ;<br>\n              Présence d’<span class=\"kw-clinique\">atrophie cutanée</span> et d’<span class=\"kw-clinique\">hyperkératose</span> ;<br>\n              <span class=\"kw-bio\">Biopsie</span> si doute.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Examens complémentaires.</strong> <span class=\"kw-alerte\">Aucun</span> examen complémentaire n’est nécessaire au diagnostic ❌ — diagnostic purement clinique.\n      </div>","frequence":8},{"id":"111-12","rang":"A","rubrique":"Contenu multimédia","titre":"Savoir reconnaître une rosacée","contenu":"<p>Reconnaissance iconographique d’une rosacée — savoir <strong>identifier la forme clinique</strong> sur une photo.</p>\n\n      <table >\n        <thead>\n          <tr><th>Forme à reconnaître</th><th>Sémiologie visuelle clé</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Flushes</strong> (vasculaire paroxystique)</td>\n            <td>Rougeur paroxystique du visage et du cou, généralement déclenchée par un facteur identifiable (T°, <span class=\"kw-etio\">alcool</span>, aliment chaud/épicé). Aspect transitoire — par définition non figé sur photo.</td>\n          </tr>\n          <tr>\n            <td><strong>Érythémato-télangiectasique</strong></td>\n            <td><span class=\"kw-clinique\">Érythème facial permanent</span> des joues, du nez, du menton et de la partie médiane du front, parsemé de <span class=\"kw-clinique\">télangiectasies</span> (couperose) visibles à l’œil nu.</td>\n          </tr>\n          <tr>\n            <td><strong>Papulo-pustuleuse</strong></td>\n            <td>Papules inflammatoires + pustules sur fond d’<span class=\"kw-clinique\">érythème</span> permanent du visage central ; <span class=\"kw-alerte\">absence de comédons</span> (clé du <span class=\"kw-def\">diagnostic différentiel</span> avec l’acné).</td>\n          </tr>\n          <tr>\n            <td><strong>Rhinophyma</strong></td>\n            <td>Homme &gt;<span class=\"kw-chiffre\"> 50 ans</span>, nez volumineux, rouge, à surface bosselée, avec <span class=\"kw-clinique\">orifices folliculaires dilatés</span> ; aspect de « trogne » — sans signification éthylique.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>À compléter (images).</strong> La fiche source du dossier <code>111/Dermatoses faciales (111)/Rosacée/</code> renvoie à des galeries d’images (formes vasculaires, papulo-pustuleuse, rhinophyma) mais aucun fichier exploitable n’est joint au build initial. Kevin déposera des photos cliniques de référence dans <code>assets/images/111/</code> pour chacune des 4 formes — chaque image sera ensuite intégrée via <code>&lt;figure class=\"obj-figure\"&gt;</code>.\n      </div>\n      <!-- TODO Kevin : déposer photos cliniques rosacée dans assets/images/111/ -->","frequence":1},{"id":"111-13","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie de la dermatite séborrhéique","contenu":"<p>La <span class=\"kw-def\">dermatite séborrhéique</span> (DS) est une dermatose chronique fréquente (<span class=\"kw-def\">prévalence</span> <span class=\"kw-chiffre\">1–3 %</span> en France) à prédominance <strong>masculine</strong>, qui touche préférentiellement les zones séborrhéiques.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>Maladie <span class=\"kw-etio\">inflammatoire</span>, non infectieuse, non contagieuse.</strong> Le rôle du sébum lui-même n’est pas démontré (les zones de prédilection sont séborrhéiques, mais pas de relation quantitative gravité ↔ séborrhée).\n      </div>\n\n      <h4 style=\"margin: 14px 0 6px 0;\">Rôle suspecté de <span class=\"kw-etio\">Malassezia</span> (M. furfur, M. globosa…)</h4>\n      <ul>\n        <li><strong>Localisation préférentielle</strong> dans les régions cutanées où la <span class=\"kw-clinique\">levure atteint sa plus forte densité</span> ;</li>\n        <li><strong>Efficacité des traitements antifongiques</strong> (kétoconazole, ciclopiroxolamine) ;</li>\n        <li><span class=\"kw-alerte\">Mais pas de relation quantitative</span> entre gravité de la maladie et densité de la flore levurique ❌.</li>\n      </ul>\n\n      <h4 style=\"margin: 14px 0 6px 0;\">Terrains à risque ⚠️ (DS sévère et étendue)</h4>\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Terrain</span></th><th>Particularités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Maladie de Parkinson</strong> et syndromes <strong>extra-pyramidaux iatrogènes</strong></td>\n            <td>Forme sévère et étendue plus fréquente</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Alcoolisme</span> chronique</strong></td>\n            <td>Forme plus étendue</td>\n          </tr>\n          <tr>\n            <td><strong>Carcinomes des VADS traités</strong></td>\n            <td>Forme plus sévère</td>\n          </tr>\n          <tr>\n            <td><strong>Infection par le <span class=\"kw-etio\">VIH</span></strong> ⭐</td>\n            <td>\n              Concerne <span class=\"kw-chiffre\">40 %</span> des séropositifs, jusqu’à <span class=\"kw-chiffre\">80 %</span> au <span class=\"kw-def\">stade</span> SIDA ;<br>\n              Le rôle de <em><span class=\"kw-etio\">Malassezia</span></em> spp. est <strong>fortement suspecté</strong> dans ce contexte ;<br>\n              <span class=\"kw-alerte\">Toute forme grave ou chronique doit faire réaliser une sérologie VIH</span> ⭐.\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":1},{"id":"111-14","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une dermatite séborrhéique","contenu":"<p>Diagnostic <span class=\"kw-clinique\">strictement clinique</span> — pas d’examen complémentaire en dehors du <span class=\"kw-bio\">dépistage VIH</span> dans les formes sévères ou chroniques (cf. obj-12).</p>\n\n      <h4 style=\"margin: 14px 0 6px 0;\">Forme de l’adulte</h4>\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span></strong></td><td>Hommes jeunes (<span class=\"kw-chiffre\">18–40 ans</span>)</td></tr>\n          <tr><td><strong>Aggravation</strong></td><td><span class=\"kw-clinique\">Stress émotionnel</span></td></tr>\n          <tr><td><strong>Amélioration</strong></td><td>Spontanée en <strong>été</strong></td></tr>\n          <tr>\n            <td><strong>Atteinte du visage +++</strong><br>(la plus fréquente)</td>\n            <td>\n              <span class=\"kw-clinique\">Plaques érythémateuses</span> recouvertes de petites <span class=\"kw-clinique\">squames grasses blanchâtres</span> ± <span class=\"kw-clinique\">prurit</span> ;<br>\n              Zones séborrhéiques : <strong>sillons nasogéniens</strong>, <strong>sourcils</strong>, <strong>glabelle</strong>, <strong>lisière antérieure du cuir chevelu</strong> ;<br>\n              <strong>Homme</strong> : barbe et moustache ;<br>\n              <strong>Formes étendues</strong> ⚠️ : atteinte du <span class=\"kw-clinique\">menton</span> et des <span class=\"kw-clinique\">bords ciliaires</span> (blépharite <span class=\"kw-clinique\">séborrhéique</span> possible).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Cuir chevelu</strong></td>\n            <td>\n              <strong><span class=\"kw-etio\">Pityriasis</span> capitis</strong> (forme peu sévère, la plus fréquente) : petites <span class=\"kw-clinique\">squames non adhérentes</span> → état pelliculaire au minimum ; lésions le plus souvent asymptomatiques mais <span class=\"kw-clinique\">prurit</span> et sensations de brûlure possibles.<br>\n              <strong>Pityriasis amiantacé</strong> (forme sévère) : aspect de <span class=\"kw-alerte\">« casque »</span> engainant des touffes de cheveux.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Autres localisations</strong></td>\n            <td>Tronc, région présternale : plaques annulaires/circinées à <span class=\"kw-clinique\">bordure squameuse</span> ; zones pileuses et régions génitales possibles.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin: 14px 0 6px 0;\">Forme du nouveau-né et du nourrisson</h4>\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Âge de début</strong></td><td>Après la <span class=\"kw-chiffre\">2ᵉ semaine de vie</span> chez un nouveau-né en bonne santé</td></tr>\n          <tr><td><strong>Forme typique</strong></td><td><span class=\"kw-clinique\">Croûtes jaunes du cuir chevelu</span> (« croûtes de lait » 🥛) et du visage</td></tr>\n          <tr><td><strong>Autres atteintes</strong></td><td>Possible atteinte du <strong>siège</strong> et <span class=\"kw-clinique\">squames grasses</span> des plis axillaires</td></tr>\n          <tr>\n            <td><strong>Forme étendue</strong></td>\n            <td><strong><span class=\"kw-alerte\">Érythrodermie de Leiner-Moussous</span></strong> :<br>\n              Mode d’entrée possible vers une <span class=\"kw-clinique\">dermatite atopique</span> ou un <span class=\"kw-clinique\">psoriasis</span> ;<br>\n              <span class=\"kw-clinique\">Évolution</span> souvent <span class=\"kw-clinique\">spontanément favorable</span> ;<br>\n              Traitement : <span class=\"kw-ttt\">kétoconazole en topique</span>.</td>\n          </tr>\n        </tbody>\n      </table>","frequence":1},{"id":"111-15","rang":"A","rubrique":"Contenu multimédia","titre":"Savoir reconnaître une dermatite séborrhéique","contenu":"<p>Reconnaissance iconographique — les deux tableaux à savoir identifier sur une photo.</p>\n\n      <table >\n        <thead>\n          <tr><th>Forme</th><th>Sémiologie visuelle clé</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>DS de l’adulte — visage</strong></td>\n            <td><span class=\"kw-clinique\">Plaques érythémateuses</span> recouvertes de <span class=\"kw-clinique\">squames grasses jaunâtres</span> dans les <strong>sillons nasogéniens</strong>, sur les <strong>sourcils</strong>, la <strong>glabelle</strong>, la <strong>lisière antérieure du cuir chevelu</strong> ; chez l’homme, atteinte de la barbe/moustache. Forme sévère : extension menton + bords ciliaires (blépharite).</td>\n          </tr>\n          <tr>\n            <td><strong>DS de l’adulte — cuir chevelu</strong></td>\n            <td>État pelliculaire de petites squames non adhérentes (<em><span class=\"kw-etio\">pityriasis</span> capitis</em>) ; ou aspect de <span class=\"kw-alerte\">« casque » engainant des touffes de cheveux</span> (<em>pityriasis amiantacé</em>).</td>\n          </tr>\n          <tr>\n            <td><strong>Croûtes de lait du nourrisson</strong></td>\n            <td>Croûtes jaunes recouvrant le cuir chevelu et le visage, apparues après la <span class=\"kw-chiffre\">2ᵉ semaine de vie</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Érythrodermie de Leiner-Moussous</strong></td>\n            <td>Forme étendue du nourrisson — <span class=\"kw-clinique\">érythème</span> généralisé + squames grasses, sans altération de l’état général ; régression spontanée fréquente.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>À compléter (images).</strong> La fiche source du dossier <code>111/Dermatoses faciales (111)/<span class=\"kw-clinique\">Dermatite</span> <span class=\"kw-clinique\">séborrhéique</span>/</code> renvoie à des galeries d’images (forme adulte visage/cuir chevelu, croûtes de lait, Leiner-Moussous) mais aucun fichier exploitable n’est joint au build initial. Kevin déposera des photos cliniques dans <code>assets/images/111/</code> pour chaque tableau — chaque image sera ensuite intégrée via <code>&lt;figure class=\"obj-figure\"&gt;</code>.\n      </div>\n      <!-- TODO Kevin : déposer photos cliniques dermatite séborrhéique dans assets/images/111/ -->","frequence":0},{"id":"111-16","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principaux diagnostics différentiels","contenu":"<p>Diagnostics différentiels de la <strong><span class=\"kw-clinique\">dermatite</span> <span class=\"kw-clinique\">séborrhéique</span></strong> — l’association DS + rosacée est possible chez un même individu (« dermatose mixte du visage »).</p>\n\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Diagnostic différentiel</span></th><th>Caractéristiques discriminantes</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Sébopsoriasis</strong></td>\n            <td><span class=\"kw-def\">Psoriasis</span> des régions séborrhéiques — souvent <span class=\"kw-alerte\">indifférenciable cliniquement</span> ❌.<br>\n              Le diagnostic repose sur la recherche de <strong>localisations extra-faciales</strong> (coudes, genoux, ongles, cuir chevelu, ombilic) et les <span class=\"kw-clinique\">ATCD personnels/familiaux</span> de <span class=\"kw-clinique\">psoriasis</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Dermatite</span> <span class=\"kw-etio\">atopique</span> de l’adulte</strong></td>\n            <td>Diagnostic difficile si la DA persiste uniquement à la tête et au cou ;<br>\n              Toutefois, la DA dépasse largement les localisations typiques des régions séborrhéiques.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Dermatite</span> <span class=\"kw-etio\">atopique</span> de l’enfant</strong></td>\n            <td><span class=\"kw-clinique\">Érythrodermie de Leiner-Moussous</span> chez le nourrisson :<br>\n              Peut être un <strong>mode d’entrée</strong> vers une <span class=\"kw-clinique\">dermatite</span> <span class=\"kw-etio\">atopique</span> ou un <span class=\"kw-clinique\">psoriasis</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Rosacée</strong></td>\n            <td>Bouffées vasomotrices, télangiectasies, papulo-pustules ; localisations centrales (joues, nez, menton, front central) ;<br>\n              ⚠️ <strong>Association possible</strong> avec la DS (« dermatose mixte du visage »). Cf. obj-10.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Lupus</span> érythémateux</strong></td>\n            <td>Atteinte malaire en vespertilio, <span class=\"kw-clinique\">photosensibilité</span>, atrophie cutanée, hyperkératose ; <span class=\"kw-bio\">biopsie</span> + bilan immunologique si doute.</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré d'<span class=\"kw-alerte\">urgence</span> :</strong> globalement <span class=\"kw-def\">non urgent</span>, prise en charge ambulatoire ; seule exception = <span class=\"kw-alerte\">acné fulminante</span> (forme aiguë fébrile).<br><strong>Acné fulminante :</strong> début brutal avec <span class=\"kw-alerte\">altération de l'état général</span>, <span class=\"kw-alerte\">hyperthermie 39-40 °C</span>, <span class=\"kw-clinique\">arthralgies</span> et <span class=\"kw-alerte\">nodules ulcéro-nécrotiques et hémorragiques</span> → avis spécialisé.<br><strong>Délai d'efficacité :</strong> les traitements ne sont jamais rapides (<span class=\"kw-chiffre\">2 à 3 mois</span> en moyenne) → prévenir le patient (observance souvent médiocre chez l'adolescent).<br><strong>1er geste :</strong> <span class=\"kw-ttt\">traitement local</span> le soir sur tout le visage + <span class=\"kw-ttt\">crème hydratante</span> le matin ; ne pas presser les <span class=\"kw-clinique\">comédons</span>.</p>","hospit":"<p><strong>Ambulatoire :</strong> la quasi-totalité des dermatoses faciales relève d'une prise en charge en ville.<br><strong>Recours au dermatologue :</strong> prescription d'<span class=\"kw-ttt\">isotrétinoïne</span> (prescription réglementée, carnet de <span class=\"kw-def\">suivi</span>) et acné sévère/cicatricielle.<br><strong>Endocrinologue / gynécologue :</strong> <span class=\"kw-etio\">acné féminine grave et résistante</span> avec <span class=\"kw-clinique\">signes d'hyperandrogénie</span> (hirsutisme, alopécie, troubles des règles) → <span class=\"kw-imagerie\">échographie abdomino-pelvienne</span> (recherche de <span class=\"kw-etio\">SOPK</span>) et <span class=\"kw-bio\">testostérone libre, 17OH-progestérone, sulfate de DHA</span> ; contraception en concertation avec le gynécologue.<br><strong><span class=\"kw-def\">Dépistage</span> <span class=\"kw-etio\">VIH</span> :</strong> toute <span class=\"kw-etio\">dermatite séborrhéique</span> <span class=\"kw-alerte\">grave ou chronique</span> impose une <span class=\"kw-bio\">sérologie VIH</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Acné fulminante</span> : <span class=\"kw-alerte\">altération de l'état général</span>, <span class=\"kw-alerte\">fièvre 39-40 °C</span>, <span class=\"kw-clinique\">arthralgies</span>, <span class=\"kw-alerte\">nodules ulcéro-nécrotiques et hémorragiques</span>, <span class=\"kw-bio\">hyperleucocytose</span></li><li><span class=\"kw-etio\">Acné nodulaire (conglobata)</span> : risque d'<span class=\"kw-etio\">abcès</span>, de <span class=\"kw-etio\">sinus</span> et de <span class=\"kw-alerte\">cicatrices</span> définitives</li><li><span class=\"kw-etio\">Acné féminine grave et résistante</span> + <span class=\"kw-clinique\">signes d'hyperandrogénie</span> → rechercher une <span class=\"kw-etio\">endocrinopathie</span> / <span class=\"kw-etio\">SOPK</span></li><li><span class=\"kw-alerte\">Risque cicatriciel</span>, en particulier cicatrices <span class=\"kw-clinique\">déprimées et hyperpigmentées</span> sur <span class=\"kw-clinique\">peau foncée</span></li><li><span class=\"kw-etio\">Dermatite séborrhéique</span> sévère/étendue ou chronique → <span class=\"kw-bio\">sérologie VIH</span> (<span class=\"kw-chiffre\">40 %</span> des séropositifs, jusqu'à <span class=\"kw-chiffre\">80 %</span> au <span class=\"kw-def\">stade</span> SIDA)</li><li><span class=\"kw-etio\">Rosacée</span> de sémiologie inhabituelle → chercher une <span class=\"kw-ci\">corticothérapie locale</span> (<span class=\"kw-etio\">rosacée stéroïdienne</span>)</li><li><span class=\"kw-etio\">Complications oculaires</span> de la rosacée (<span class=\"kw-clinique\">conjonctivites, blépharites, kératites</span>), présentes chez <span class=\"kw-chiffre\">30-50 %</span></li></ul>","principes":"<p>Traitement adapté au diagnostic et, pour l'acné, au <span class=\"kw-def\">grade</span> de gravité (<span class=\"kw-def\">échelle GEA</span>) ; traitement d'attaque jugé à <span class=\"kw-chiffre\">3 mois</span>.</p><p><strong>Acné selon le <span class=\"kw-def\">grade</span> GEA</strong></p><p>Traitement d'entretien après rémission : <span class=\"kw-ttt\">adapalène</span> ± <span class=\"kw-ttt\">peroxyde de benzoyle</span></p><ul><li><span class=\"kw-chiffre\">GEA 1-2</span> (légère, < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">50 %</span></span> du visage) : traitements <span class=\"kw-ttt\">topiques</span> — <span class=\"kw-ttt\">peroxyde de benzoyle</span> ± <span class=\"kw-ttt\">rétinoïde topique</span></li><li><span class=\"kw-chiffre\">GEA 3-4</span> (moyenne à sévère, > <span class=\"kw-chiffre\">50 %</span> à tout le visage) : <span class=\"kw-ttt\">traitement topique combiné</span> + <span class=\"kw-ttt\">cyclines</span> (<span class=\"kw-ttt\">doxycycline</span>, lymécycline)</li><li><span class=\"kw-chiffre\">GEA 5</span> (très sévère, nodulaire) : <span class=\"kw-ttt\">isotrétinoïne</span> orale d'emblée</li><li>Si échec à <span class=\"kw-chiffre\">3 mois</span> : intensification puis passage à l'<span class=\"kw-ttt\">isotrétinoïne</span> orale</li></ul><p><strong><span class=\"kw-ttt\">Isotrétinoïne</span> : encadrement strict</strong></p><p>Seul traitement pouvant induire des guérisons ; dose cumulée <span class=\"kw-chiffre\">120-150 mg/kg</span></p><ul><li><span class=\"kw-alerte\">Tératogène</span> : <span class=\"kw-ttt\">contraception efficace</span> débutée <span class=\"kw-chiffre\">1 mois avant</span>, poursuivie tout le traitement, arrêtée <span class=\"kw-chiffre\">1 mois après</span></li><li><span class=\"kw-bio\">β-hCG plasmatiques</span> mensuels, le dernier <span class=\"kw-chiffre\">5 semaines après</span> l'arrêt ; consentement signé</li><li><span class=\"kw-def\">Surveillance</span> <span class=\"kw-bio\">transaminases (ASAT/ALAT) et bilan lipidique</span> tous les <span class=\"kw-chiffre\">3 mois</span></li><li><span class=\"kw-ci\">Contre-indiquée avec les cyclines</span> (risque d'<span class=\"kw-alerte\">HTIC</span>) ; évacuer les lésions rétentionnelles avant l'instauration</li></ul><p><strong>Rosacée</strong></p><p>Traitement uniquement <span class=\"kw-def\">suspensif</span> ; entretien topique au long cours</p><ul><li><span class=\"kw-clinique\">Couperose / érythrose</span> : <span class=\"kw-ttt\">laser vasculaire</span> ou <span class=\"kw-ttt\">électrocoagulation</span> ; <span class=\"kw-ttt\">tartrate de brimonidine</span> en gel</li><li>Formes mineures : <span class=\"kw-ttt\">métronidazole topique</span> (alternatives : <span class=\"kw-ttt\">acide azélaïque</span>, <span class=\"kw-ttt\">ivermectine locale</span>)</li><li>Formes diffuses : <span class=\"kw-ttt\">doxycycline</span> orale <span class=\"kw-chiffre\">3 mois</span> (active aussi sur l'atteinte oculaire)</li><li><span class=\"kw-etio\">Rhinophyma</span> installé : <span class=\"kw-ttt\">chirurgie</span> ou <span class=\"kw-ttt\">laser CO2</span></li></ul><p><strong><span class=\"kw-clinique\">Dermatite</span> <span class=\"kw-clinique\">séborrhéique</span></strong></p><p>Objectif = <span class=\"kw-def\">rémission</span>, non une guérison définitive</p><ul><li>Traitement toujours <span class=\"kw-ttt\">local</span> : <span class=\"kw-ttt\">antifongiques (kétoconazole, ciclopiroxolamine)</span>, <span class=\"kw-ttt\">gluconate de lithium</span>, <span class=\"kw-ttt\">shampooings</span> (pyrithione de zinc, sulfure de sélénium)</li><li>Forme très <span class=\"kw-etio\">inflammatoire</span> : <span class=\"kw-ttt\">dermocorticoïdes</span> modérés quelques jours puis relais non <span class=\"kw-ttt\">corticoïde</span></li><li>Nourrisson (érythrodermie de Leiner-Moussous) : <span class=\"kw-ttt\">kétoconazole topique</span></li></ul><p><strong><span class=\"kw-ci\">Contre-indications</span> & erreurs <span class=\"kw-ci\">à éviter</span></strong></p><ul><li><span class=\"kw-ci\">Dermocorticoïdes contre-indiqués</span> dans l'acné et dans la rosacée</li><li>Cyclines : <span class=\"kw-ci\">contre-indiquées chez l'enfant < 8 ans et la femme enceinte</span> ; <span class=\"kw-ci\">ne jamais</span> associer à un <span class=\"kw-ci\">ATB topique</span> ni à un <span class=\"kw-ci\">rétinoïde</span></li><li><span class=\"kw-ttt\">ATB local</span> jamais seul ni > <span class=\"kw-chiffre\">4 semaines</span> (résistances bactériennes)</li><li>Pas de <span class=\"kw-def\">régime alimentaire</span> à suivre, ne pas presser les comédons, pas d'antiseptique sur les lésions</li></ul>","suivi":"<p><strong>Rythme :</strong> traitement d'attaque évalué à <span class=\"kw-chiffre\">3 mois</span> ; traitement d'entretien maintenu après rémission (<span class=\"kw-ttt\">adapalène</span> ± <span class=\"kw-ttt\">peroxyde de benzoyle</span>).<br><strong><span class=\"kw-ttt\">Isotrétinoïne</span> :</strong> <span class=\"kw-bio\">β-hCG</span> mensuels (+ <span class=\"kw-chiffre\">5 semaines</span> après l'arrêt), <span class=\"kw-bio\">transaminases et bilan lipidique</span> tous les <span class=\"kw-chiffre\">3 mois</span>.<br><strong>Cyclines :</strong> durée limitée à <span class=\"kw-chiffre\">3 mois</span> (résistance au-delà) ; <span class=\"kw-ttt\">ATB local</span> ≤ <span class=\"kw-chiffre\">4 semaines</span>.<br><strong>Rosacée & <span class=\"kw-clinique\">dermatite</span> <span class=\"kw-clinique\">séborrhéique</span> :</strong> traitements <span class=\"kw-def\">suspensifs</span> → entretien topique au long cours.</p>"},"liensGlobaux":[{"href":"https://centredepreuves.sfdermato.org/recommandation-cdp/44-acne","label":"SF Dermato — Recommandations acné"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Dermatose faciale chronique — Lésions rétentionnelles (comédons, microkystes) présentes ?","detail":"<h4>CAT — Dermatose faciale chronique — Orientation diagnostique puis stratégie thérapeutique (acné / rosacée / <span class=\"kw-clinique\">dermatite</span> <span class=\"kw-clinique\">séborrhéique</span>)</h4>","branches":[{"to":"q-acne-grade","label":"Oui — comédons / microkystes présents","color":"blue"},{"to":"q-rosacee","label":"Non — pas de lésion rétentionnelle","color":"blue"}]},{"id":"q-acne-grade","kind":"decision","label":"Acné confirmée — évaluer la gravité — Échelle GEA : extension des lésions et nombre de nodules","branches":[{"to":"t-acne-legere","label":"Rares/quelques papulo-pustules, < 50 % du visage","color":"green"},{"to":"t-acne-moyenne","label":"Atteinte > 50 % à tout le visage, ± nodules","color":"amber"},{"to":"t-acne-severe","label":"Très inflammatoire, nodules / forme fulminante","color":"red"}]},{"id":"t-acne-legere","kind":"terminal","label":"Acné légère (GEA 1-2) — topiques","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Comédons</span>, rares à quelques <span class=\"kw-clinique\">papulo-pustules</span> sur < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">50 %</span></span> du visage</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Peroxyde de benzoyle</span> ± <span class=\"kw-ttt\">rétinoïde topique</span>, le soir sur tout le visage</li><li>Si échec à <span class=\"kw-chiffre\">3 mois</span> : associer <span class=\"kw-ttt\">ATB topique</span> + <span class=\"kw-ttt\">rétinoïde</span> (jamais d'<span class=\"kw-ci\">ATB local seul</span>)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Évaluation à <span class=\"kw-chiffre\">3 mois</span> ; entretien par <span class=\"kw-ttt\">adapalène</span> ± <span class=\"kw-ttt\">peroxyde de benzoyle</span></li></ul>"},{"id":"t-acne-moyenne","kind":"terminal","label":"Acné moyenne à sévère (GEA 3-4) — topique + cyclines","color":"amber","detail":"<h4>Clinique</h4><ul><li>Nombreux <span class=\"kw-clinique\">comédons</span> et <span class=\"kw-clinique\">papulo-pustules</span> sur > <span class=\"kw-chiffre\">50 %</span> à tout le visage, ± <span class=\"kw-clinique\">nodules</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Traitement topique combiné</span> + <span class=\"kw-ttt\">cyclines</span> (<span class=\"kw-ttt\">doxycycline</span>, lymécycline) pendant <span class=\"kw-chiffre\">3 mois</span></li><li><span class=\"kw-ci\">Ne jamais associer cyclines + ATB topique ni + rétinoïde</span> (risque d'<span class=\"kw-alerte\">HTIC</span>)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Si échec à <span class=\"kw-chiffre\">3 mois</span> : passage à l'<span class=\"kw-ttt\">isotrétinoïne</span> orale</li></ul>"},{"id":"t-acne-severe","kind":"terminal","label":"Acné très sévère / nodulaire (GEA 5) — isotrétinoïne","color":"red","detail":"<h4>Clinique</h4><ul><li>Acné <span class=\"kw-clinique\">très inflammatoire</span> avec <span class=\"kw-clinique\">nodules</span> ; surveiller la forme aiguë fébrile (<span class=\"kw-alerte\">acné fulminante</span>) et le <span class=\"kw-alerte\">risque cicatriciel</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Isotrétinoïne</span> orale d'emblée (seul traitement curatif), dose cumulée <span class=\"kw-chiffre\">120-150 mg/kg</span></li><li><span class=\"kw-alerte\">Tératogène</span> : <span class=\"kw-ttt\">contraception</span> de <span class=\"kw-chiffre\">1 mois avant</span> à <span class=\"kw-chiffre\">1 mois après</span>, <span class=\"kw-bio\">β-hCG</span> mensuels</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-bio\">Transaminases + bilan lipidique</span> tous les <span class=\"kw-chiffre\">3 mois</span> ; <span class=\"kw-ci\">contre-indication avec les cyclines</span></li></ul><h4>Conduite</h4><ul><li>Rechercher une <span class=\"kw-etio\">endocrinopathie</span> / <span class=\"kw-etio\">SOPK</span> si acné féminine grave résistante + <span class=\"kw-clinique\">hyperandrogénie</span></li></ul>"},{"id":"q-rosacee","kind":"decision","label":"Pas d'acné (absence de comédon) — Bouffées vasomotrices et/ou télangiectasies (couperose) ?","branches":[{"to":"t-rosacee","label":"Oui — flushes / télangiectasies","color":"amber"},{"to":"t-ds","label":"Non — érythème + squames grasses","color":"amber"}]},{"id":"t-rosacee","kind":"terminal","label":"Rosacée","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Bouffées vasomotrices (flushes)</span>, <span class=\"kw-clinique\">érythème permanent</span> + <span class=\"kw-clinique\">télangiectasies</span>, <span class=\"kw-clinique\">papulo-pustules</span> sans <span class=\"kw-clinique\">comédon</span> ; rechercher des <span class=\"kw-etio\">complications oculaires</span></li></ul><h4>Traitement</h4><ul><li>Formes mineures : <span class=\"kw-ttt\">métronidazole topique</span> (ou <span class=\"kw-ttt\">ivermectine</span>, <span class=\"kw-ttt\">acide azélaïque</span>) ; formes diffuses : <span class=\"kw-ttt\">doxycycline</span> <span class=\"kw-chiffre\">3 mois</span></li><li>Couperose : <span class=\"kw-ttt\">laser vasculaire</span> ; <span class=\"kw-ci\">dermocorticoïdes contre-indiqués</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Traitement <span class=\"kw-def\">suspensif</span> ; écarter une <span class=\"kw-etio\">rosacée stéroïdienne</span> si sémiologie inhabituelle</li></ul>"},{"id":"t-ds","kind":"terminal","label":"Dermatite séborrhéique","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Plaques érythémateuses</span> recouvertes de <span class=\"kw-clinique\">squames grasses</span> des sillons nasogéniens, sourcils, lisière antérieure du cuir chevelu</li></ul><h4>Traitement</h4><ul><li>Traitement <span class=\"kw-ttt\">local</span> : <span class=\"kw-ttt\">antifongiques (kétoconazole)</span>, <span class=\"kw-ttt\">gluconate de lithium</span>, <span class=\"kw-ttt\">shampooings antifongiques</span></li></ul><h4>Conduite</h4><ul><li>Forme <span class=\"kw-alerte\">grave ou chronique</span> → <span class=\"kw-bio\">sérologie VIH</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Traitement <span class=\"kw-def\">suspensif</span>, entretien séquentiel au long cours</li></ul>"}]},"cards":[{"i":"0c5075d50426","n":111,"o":"111-1","u":"Définition","t":"Connaître la définition de l’acné","q":"Quels sont les mécanismes physiopathologiques clés de l'acné ?","a":"<ul><li>La <strong>séborrhée</strong> (production excessive de sébum)</li><li>La <strong>kératinisation infundibulaire</strong> anormale (formation du comédon)</li><li>L'<strong>inflammation</strong>, notamment due à <em>Cutibacterium acnes</em></li></ul>"},{"i":"121f72f21422","n":111,"o":"111-1","u":"Définition","t":"Connaître la définition de l’acné","q":"Quelle est la définition générale de l'acné ?","a":"<p>L'acné est une <strong>dermatose inflammatoire chronique</strong> du <strong>follicule pilo-sébacé</strong>, de nature <strong>non infectieuse</strong>.</p>"},{"i":"da2d4a772a79","n":111,"o":"111-1","u":"Définition","t":"Connaître la définition de l’acné","q":"Quel est le rôle précis des androgènes dans la physiopathologie de l'acné ?","a":"<p>C'est l'<strong>hypersensibilité des récepteurs androgéniques</strong> du sébocyte qui est en cause, et <strong>non</strong> un excès d'androgènes circulants.</p>"},{"i":"249ee4d17df2","n":111,"o":"111-11","u":"Diagnostic positif","t":"Savoir diagnostiquer une rosacée","q":"Quels sont les facteurs déclenchants et d'aggravation des manifestations de la rosacée ?","a":"<ul><li><strong>Changements de températures</strong> (climat continental, travail à la chaleur).</li><li><strong>Exposition solaire</strong>.</li><li><strong>Boissons et aliments chauds</strong>.</li><li><strong>Alcool</strong>.</li><li><strong>Aliments épicés</strong>.</li></ul>"},{"i":"4c28ed820c2d","n":111,"o":"111-11","u":"Diagnostic positif","t":"Savoir diagnostiquer une rosacée","q":"Quelle est la particularité de la forme hypertrophique de la rosacée (rhinophyma) ?","a":"<ul><li>Elle touche principalement les <strong>hommes (> 95 %)</strong>, souvent <strong>> 50 ans</strong>.</li><li>Elle se manifeste par une augmentation du volume du nez, une rougeur diffuse, des orifices folliculaires dilatés et un épaississement progressif de la peau qui devient fibreuse.</li><li>Une fois installée, cette forme <strong>ne régresse plus spontanément</strong> et n'est <strong>sensible à aucun traitement médical</strong>. Le traitement est chirurgical ou par laser CO2.</li><li>L'<strong>alcool n'est pas en cause</strong> dans son apparition, contrairement à une idée reçue.</li></ul>"},{"i":"701e6fe53282","n":111,"o":"111-11","u":"Diagnostic positif","t":"Savoir diagnostiquer une rosacée","q":"Quelles sont les trois formes cliniques principales de la rosacée ?","a":"<ul><li>La forme <strong>vasculaire paroxystique</strong> (flushes).</li><li>La forme <strong>vasculaire permanente</strong> (rosacée érythémato-télangiectasique ou couperose).</li><li>La forme <strong>papulo-pustuleuse</strong> (la plus caractéristique).</li></ul>"},{"i":"8b3c44099a82","n":111,"o":"111-11","u":"Diagnostic positif","t":"Savoir diagnostiquer une rosacée","q":"Quelles sont les complications oculaires fréquentes de la rosacée ?","a":"<p>Les complications oculaires de la rosacée, touchant <strong>30 à 50 % des patients</strong>, incluent :</p><ul><li>Sécheresse oculaire.</li><li><strong>Conjonctivites</strong>.</li><li><strong>Blépharites</strong>.</li><li>Plus rarement, des <strong>kératites</strong>.</li></ul>"},{"i":"93298cf7ed62","n":111,"o":"111-11","u":"Diagnostic positif","t":"Savoir diagnostiquer une rosacée","q":"Comment différencier cliniquement la rosacée d'une acné ?","a":"<p>La rosacée se distingue de l'acné par :</p><ul><li>Un <strong>terrain différent</strong> (adulte > 20 ans pour la rosacée, adolescent pour l'acné).</li><li>L'<strong>absence de lésions rétentionnelles</strong> (comédons et microkystes) dans la rosacée.</li><li>L'<strong>absence de séborrhée</strong> associée.</li><li>La présence de <strong>bouffées vasomotrices</strong> dans la rosacée.</li></ul>"},{"i":"bbe835fadb37","n":111,"o":"111-11","u":"Diagnostic positif","t":"Savoir diagnostiquer une rosacée","q":"Quels sont les éléments du terrain évocateur de la rosacée ?","a":"<ul><li><strong>Phototype :</strong> Sujets à <strong>peau claire, yeux clairs, cheveux clairs</strong>.</li><li><strong>Sex-ratio :</strong> Prédominance <strong>féminine</strong> (2 F / 1 H).</li><li><strong>Âge :</strong> Adulte <strong>> 20 ans</strong>, avec un pic de fréquence à <strong>40-50 ans</strong>.</li></ul>"},{"i":"da07b98690a8","n":111,"o":"111-11","u":"Diagnostic positif","t":"Savoir diagnostiquer une rosacée","q":"Comment doit-on diagnostiquer une rosacée ?","a":"<p>Le diagnostic de la rosacée est purement <strong>clinique</strong>. Il repose sur l'association d'un <strong>terrain évocateur</strong>, d'une <strong>sémiologie caractéristique</strong> et de l'<strong>absence de lésions rétentionnelles</strong>.</p>"},{"i":"6fb88dc67a22","n":111,"o":"111-12","u":"Contenu multimédia","t":"Savoir reconnaître une rosacée","q":"Comment se présente iconographiquement un rhinophyma lié à la rosacée ?","a":"<p>Un rhinophyma se présente iconographiquement comme un <strong>nez volumineux</strong>, <strong>rouge</strong>, avec une <strong>surface bosselée</strong> et des <strong>orifices folliculaires dilatés</strong>. Il touche préférentiellement les hommes de plus de 50 ans et donne un aspect de « trogne », sans signification éthylique obligatoire.</p>"},{"i":"c57bbb1a2111","n":111,"o":"111-12","u":"Contenu multimédia","t":"Savoir reconnaître une rosacée","q":"Comment identifier iconographiquement un flush chez un patient atteint de rosacée ?","a":"<p>Un flush, dans le cadre de la rosacée, se manifeste par une <strong>rougeur paroxystique</strong> du visage et du cou. Il est généralement déclenché par un facteur identifiable (température, alcool, aliment chaud ou épicé) et est par définition <strong>transitoire</strong>, donc non figé sur une photo isolée.</p>"},{"i":"e488698a72e4","n":111,"o":"111-12","u":"Contenu multimédia","t":"Savoir reconnaître une rosacée","q":"Quels sont les signes iconographiques clés de la forme érythémato-télangiectasique de la rosacée ?","a":"<p>Les signes clés de la forme érythémato-télangiectasique de la rosacée sont un <strong>érythème facial permanent</strong> localisé sur les joues, le nez, le menton et la partie médiane du front. Cet érythème est parsemé de <strong>télangiectasies</strong> (couperose) bien visibles à l'œil nu.</p>"},{"i":"ec0a6cd08a56","n":111,"o":"111-12","u":"Contenu multimédia","t":"Savoir reconnaître une rosacée","q":"Comment reconnaître iconographiquement la forme papulo-pustuleuse de la rosacée et la différencier de l'acné ?","a":"<p>La forme papulo-pustuleuse de la rosacée est caractérisée par la présence de <strong>papules inflammatoires</strong> et de <strong>pustules</strong> sur un fond d'<strong>érythème permanent</strong>, siégeant sur la partie centrale du visage. L'absence de <strong>comédons</strong> est un élément clé pour la différencier de l'acné.</p>"},{"i":"9eddf98ec45d","n":111,"o":"111-14","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une dermatite séborrhéique","q":"Dans quel cas doit-on envisager un dépistage VIH face à une dermatite séborrhéique ?","a":"<p>Un dépistage VIH doit être envisagé devant une dermatite séborrhéique dans les <strong>formes sévères ou chroniques</strong>.</p>"},{"i":"a437e17008bc","n":111,"o":"111-14","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une dermatite séborrhéique","q":"Quelles sont les particularités de la dermatite séborrhéique chez le nouveau-né et le nourrisson ?","a":"<p>Chez le nouveau-né et le nourrisson, la dermatite séborrhéique apparaît après la <strong>2<sup>ème</sup> semaine de vie</strong>. Elle se manifeste par des <strong>croûtes jaunes du cuir chevelu</strong> (« croûtes de lait »), du visage, parfois du siège et des plis. La forme la plus sévère est l'<strong>érythrodermie de Leiner-Moussous</strong>.</p>"},{"i":"d8f2f68abe4a","n":111,"o":"111-14","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une dermatite séborrhéique","q":"Quels sont les éléments clés du diagnostic de la dermatite séborrhéique chez l'adulte ?","a":"<p>Le diagnostic de la dermatite séborrhéique chez l'adulte est <strong>strictement clinique</strong>. Il se caractérise par des <strong>plaques érythémateuses</strong> recouvertes de petites <strong>squames grasses blanchâtres</strong>, avec parfois du prurit. Elles touchent les <strong>zones séborrhéiques</strong> : sillons nasogéniens, sourcils, glabelle, lisière antérieure du cuir chevelu, barbe et moustache chez l'homme.</p>"},{"i":"f7b014c08ca2","n":111,"o":"111-14","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une dermatite séborrhéique","q":"Quelles sont les localisations de la dermatite séborrhéique chez l'adulte en dehors du visage ?","a":"<ul><li><strong>Cuir chevelu</strong> :</li><ul><li><strong>Pityriasis capitis</strong> (état pelliculaire)</li><li><strong>Pityriasis amiantacé</strong> (aspect de « casque » engainant les cheveux)</li></ul><li><strong>Tronc</strong> : plaques annulaires/circinées à bordure squameuse en région présternale.</li><li>Autres zones pileuses et régions génitales.</li></ul>"},{"i":"100af158cb92","n":111,"o":"111-3","u":"Diagnostic positif","t":"Connaître les éléments cliniques permettant de diagnostiquer une acné","q":"Quelles sont les caractéristiques des lésions rétentionnelles de l'acné, et leur importance diagnostique ?","a":"<ul><li>Les lésions rétentionnelles sont de deux types : les <strong>comédons fermés</strong> (microkystes), qui sont de petites papules couleur peau normale, et les <strong>comédons ouverts</strong> (points noirs), qui sont de petites lésions de 1 à 3 mm.</li><li>Leur présence est <strong>nécessaire au diagnostic d'acné</strong>. Leur absence doit faire reconsidérer le diagnostic.</li></ul>"},{"i":"1e1884a131f7","n":111,"o":"111-3","u":"Diagnostic positif","t":"Connaître les éléments cliniques permettant de diagnostiquer une acné","q":"Décrivez les différents types de lésions inflammatoires de l'acné.","a":"<ul><li>Les <strong>lésions inflammatoires superficielles</strong> comprennent les <strong>papules</strong> (petites surélévations rouges, fermes, parfois douloureuses, de moins de 1 cm) et les <strong>pustules</strong> (papules surmontées d'un contenu purulent jaune).</li><li>Les <strong>lésions inflammatoires profondes</strong> sont des <strong>nodules</strong> (lésions de plus de 1 cm atteignant le derme, pouvant évoluer vers un abcès ou des cicatrices) et, en cas de rupture profonde, des sinus.</li></ul>"},{"i":"82832d553798","n":111,"o":"111-3","u":"Diagnostic positif","t":"Connaître les éléments cliniques permettant de diagnostiquer une acné","q":"Quelle est la triade lésionnelle clinique caractéristique permettant de diagnostiquer une acné ?","a":"<p>Le diagnostic d'acné repose sur l'association de <strong>séborrhée</strong>, de <strong>lésions rétentionnelles</strong> et de <strong>lésions inflammatoires</strong>, toutes localisées sur les zones séborrhéiques (visage central, dos, face antérieure du thorax).</p>"}]};